import{_ as a,o as s,c as t,a5 as r}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse('{"title":"Assistant IA (MCP) et propositions","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/18-mcp.md","filePath":"generated/modules/18-mcp.md","lastUpdated":null}'),n={name:"modules/18-mcp.md"};function i(d,e,o,l,p,u){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="assistant-ia-mcp-et-propositions" tabindex="-1">Assistant IA (MCP) et propositions <a class="header-anchor" href="#assistant-ia-mcp-et-propositions" aria-label="Permalink to &quot;Assistant IA (MCP) et propositions&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/18-mcp">spécification complète</a></span></p><p>Assistant IA du commerçant branché par le protocole MCP : il répond aux questions (lecture) et peut préparer des actions qu&#39;un responsable valide toujours. Le jalon 1 du projet « écriture » (VEN-45 → VEN-48, 16 et 17/11/2026) pose le socle générique : registre de types, allumage par type, familles de propositions réglées par le gérant, par clé et par connexion, écran de décision unique sur le back-office et les deux apps caisse. Aucun type nouveau n&#39;est ouvert : les trois actions existantes (bon de commande, prix, alerte de fraude) tournent sur le socle. Les lectures (outils, OAuth, démonstration) restent décrites dans la vue d&#39;ensemble.</p><div class="kpis"><div><b>15</b><span>faites</span></div><div><b>13</b><span>partielles</span></div><div><b>8</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="propositions-de-l-assistant-—-socle-generique" tabindex="-1">Propositions de l&#39;assistant — socle générique <a class="header-anchor" href="#propositions-de-l-assistant-—-socle-generique" aria-label="Permalink to &quot;Propositions de l&#39;assistant — socle générique&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Registre des types de proposition</strong><br><span class="muted">Chaque action que l&#39;assistant peut préparer est décrite en un seul endroit du serveur : ce qu&#39;il peut remplir, ce qu&#39;il n&#39;a jamais le droit de toucher, qui valide et où. Ajouter un type devient déclaratif et ne peut plus affaiblir les garde-fous.<br><i>Les trois types de VEN-34 (bon de commande, changement de prix, traitement d&#39;une alerte) sont migrés sans changer leur comportement. Garde des exclusions (fiscal, argent, sécurité et accès, abonnement, envois, suppressions, TVA) vérifiée au démarrage et par test ; champs fermés par type ; propositions groupées (100 lignes au plus, tout ou rien) ; demande répétée reconnue sans doublon ni quota consommé. Aucun type nouveau n&#39;est ouvert à ce jalon. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-84, RG-MCP-106, RG-MCP-107, RG-MCP-108, RG-MCP-115, RG-MCP-116, RG-MCP-117, RG-MCP-119, RG-MCP-122, RG-MCP-123, RG-MCP-129, RG-MCP-130, RG-MCP-132</td><td>VEN-45, VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Allumage de chaque type par l&#39;exploitation</strong><br><span class="muted">Vendora allume les types d&#39;action un par un : un type nouveau est livré éteint et ne devient disponible qu&#39;après sa revue de sécurité.<br><i>Variable d&#39;exploitation par type ; un type éteint se comporte comme l&#39;interrupteur général éteint pour lui seul (création refusée, outil non listé, propositions existantes toujours décidables). Migration V124 : les accès qui proposaient déjà gardent leurs trois types sans geste. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-104, RG-MCP-110</td><td>VEN-45</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Familles de propositions réglées par le gérant</strong><br><span class="muted">Dans Réglages › Assistant IA, le propriétaire ou un administrateur choisit, famille par famille, ce que l&#39;assistant a le droit de proposer (catalogue, achats, anti-fraude…). Éteint par défaut pour un nouveau commerce.<br><i>Huit familles existent (catalogue, stock, achats, restaurant, clients, réglages, appareils, anti-fraude) ; seules Catalogue, Achats et Anti-fraude portent aujourd&#39;hui des actions. Réglage réservé à la session d&#39;un propriétaire ou d&#39;un administrateur : une clé ou un jeton reçoit 403, un assistant ne peut jamais élargir ses droits ; changements inscrits au journal d&#39;audit. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec. Libellés des types fournis par le serveur en français, anglais et arabe (RG-MCP-137, lot MCP-ECRITURE-LIBELLES, 18/11/2026) : un type ajouté s&#39;affiche tout de suite par son nom en clair, sans retouche du back-office, et un libellé manquant fait échouer la construction.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-109, RG-MCP-111, RG-MCP-137</td><td>VEN-45, VEN-48, MCP-ECRITURE-LIBELLES</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-18-libelles">📷</a></td></tr><tr><td><strong>Familles de propositions par clé d&#39;API et par connexion d&#39;assistant</strong><br><span class="muted">Quand le gérant crée une clé « Assistant IA » ou autorise la connexion d&#39;un assistant, il coche les familles que cet accès peut proposer ; rien n&#39;est coché d&#39;office, et une clé ne reçoit jamais une famille d&#39;elle-même.<br><i>Bloc « Préparer des propositions » sur le formulaire de clé et sur l&#39;écran de consentement OAuth (FR / EN / AR, clair / sombre) ; avertissements quand la lecture du domaine manque ; badges « Lecture et propositions » / « Lecture seule » sur les accès ; nouvelle famille de lecture « Réglages » au consentement. Une seule portée d&#39;écriture reste : proposals:write. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-111, RG-MCP-112</td><td>VEN-45, VEN-48</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Écran de décision générique des propositions</strong><br><span class="muted">Un seul écran, le même pour toutes les actions que l&#39;assistant propose : ce qui change (avant → après), les chiffres de Vendora datés, le risque, puis valider ou refuser au back-office, ou sur la caisse avec le PIN d&#39;un responsable.<br><i>Le serveur fournit le modèle d&#39;affichage (cinq blocs fermés, valeurs typées) : les écrans ne connaissent plus les types. Filtre par famille, tri par risque puis échéance, saisie du validateur, case de confirmation renforcée avant le PIN, états (déjà traitée, périmée avec la raison, expirée, appliquée), prix de l&#39;entreprise lisible sur les caisses, « Back-office seulement » pour les types qui s&#39;y décident. Back-office, iPhone / iPad, téléphone et tablette Android ; français, anglais, arabe (RTL), sombre. Écarts restants listés dans le README des captures (E1 à E8). Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-91, RG-MCP-113, RG-MCP-114, RG-MCP-120, RG-MCP-121, RG-MCP-131</td><td>VEN-45, VEN-47</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a></td></tr><tr><td><strong>Outils de proposition de l&#39;assistant (fabrique d&#39;outils)</strong><br><span class="muted">L&#39;assistant ne voit que les actions que son accès peut réellement proposer ; ses montants sont compris sans ambiguïté et ses refus lui sont expliqués en clair.<br><i>Fabrique d&#39;outils d&#39;écriture dans le serveur MCP (un outil par objet métier, paramètre « action » fermé) ; liste d&#39;outils calculée d&#39;après ce que l&#39;accès peut proposer ; montants lus sans facteur 1 000 ni forme illisible acceptée (chiffres arabes compris) ; refus de famille relayés ; une seule écriture possible, la création d&#39;une proposition (liste blanche testée). Évaluations d&#39;écriture ajoutées au jeu de référence. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-100, RG-MCP-101, RG-MCP-128</td><td>VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Suivi de ses propositions par l&#39;assistant</strong><br><span class="muted">L&#39;assistant peut dire où en sont les propositions qu&#39;il a préparées (en attente, appliquées, refusées, expirées) sans jamais voir la justification du responsable ni son commentaire.<br><i>Outil list_proposals côté MCP et vue GET /api/v1/agent-proposals/mine côté serveur, bornée par la portée de lecture de l&#39;accès ; sans justification, sans commentaire libre du refus et sans nom du validateur ; absent de la démonstration publique. Tests du jalon, relancés de zéro le 17/11 : moteur partagé 849 (JVM) et 835 (iOS), serveur 864, MCP 326, Android 695, iOS 557, web 1 168, console 121, 0 échec.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-127</td><td>VEN-45, VEN-46</td><td><a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Revue de sécurité de l&#39;écriture, vague 1</strong><br><span class="muted">Avant d&#39;ouvrir d&#39;autres actions à l&#39;assistant, 15 attaques ont été essayées sur le socle et les quatre types existants : aucune n&#39;a abouti. Une garde automatique empêche désormais un futur type d&#39;appeler un service interdit.<br><i>VEN-58 vague 1, 18/11/2026 (rapport docs/securite/MCP-ECRITURE-VAGUE-1.md). 15 attaques essayées et parées (consignes cachées dans un nom de produit, un motif ou un fournisseur ; justification hostile ; tromperie visuelle ; champ fermé ; clé standard avec portée d&#39;écriture ; outil appelé type éteint ; autre commerce ou autre magasin ; fatigue de validation ; remplacement furtif). Textes piégés tenus 18 passes sur 18 sous claude-sonnet-5-5. Garde par appels déclarés (chaque type déclare les services qu&#39;il appelle) vérifiée sur le code compilé : un appel non déclaré ou interdit fait échouer le test. Un défaut réel corrigé côté MCP (un outil d&#39;écriture ne regardait pas l&#39;interrupteur général), non exploitable. Plus aucune écriture SQL dans un applicateur. Relecture de code dédiée OK au troisième passage ; avis fiscal conforme sous réserves. Restes = limites écrites au rapport (la garde ne voit pas les arguments d&#39;un appel, test de source obligatoire par type) ; vagues suivantes : familles stock et achats. Revue complète de PRODUCT_CREATE faite le 19/11/2026 (docs/securite/MCP-ECRITURE-PRODUIT-CREER.md) : un défaut bloquant trouvé et corrigé (nom à caractère invisible).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-138, RG-MCP-139</td><td>VEN-58</td><td></td></tr></tbody></table><h2 id="types-de-proposition-deja-livres-ven-34" tabindex="-1">Types de proposition déjà livrés (VEN-34) <a class="header-anchor" href="#types-de-proposition-deja-livres-ven-34" aria-label="Permalink to &quot;Types de proposition déjà livrés (VEN-34)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Bon de commande proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant prépare un bon de commande en brouillon à partir des besoins de réassort ; un responsable le relit et le valide, et le brouillon est créé à son nom.<br><i>Livré par VEN-34 (15/11/2026), migré sur le registre par VEN-45, rendu par l&#39;écran générique depuis le socle. Le bon reste un brouillon : jamais envoyé au fournisseur par l&#39;assistant.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Changement de prix proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose un nouveau prix de vente (ancien prix, nouveau, écart) ; seul le prix change, jamais la TVA ni la disponibilité ; un responsable valide, avec une case de confirmation au-delà de 30 % d&#39;écart.<br><i>Prix de l&#39;entreprise ou d&#39;un magasin, sous verrou commun des surcharges ; les ventes déjà faites gardent leur prix. Depuis le socle, la case « plus de 30 % » apparaît aussi sur la caisse avant le PIN et un prix de l&#39;entreprise se lit (sans se décider) sur les caisses.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr><tr><td><strong>Traitement d&#39;une alerte anti-fraude proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose d&#39;acquitter ou d&#39;écarter une alerte avec un motif ; le responsable relit, modifie le motif si besoin et décide : la décision ne s&#39;annule pas.<br><i>Motif pré-rempli par l&#39;assistant et modifiable, marqué comme tel ; résumé de l&#39;alerte composé par Vendora et traduit à la lecture (FR / EN / AR).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-83, RG-MCP-84</td><td>VEN-34</td><td><a href="/VendoraSystem-docs/preuves/2026-11-15-VEN-34-propositions">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-17-socle-propositions">📷</a></td></tr></tbody></table><h2 id="types-de-proposition-allumes-sur-le-staging" tabindex="-1">Types de proposition allumés sur le staging <a class="header-anchor" href="#types-de-proposition-allumes-sur-le-staging" aria-label="Permalink to &quot;Types de proposition allumés sur le staging&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Disponibilité d&#39;un produit proposée par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de rendre un ou plusieurs produits (20 au plus) indisponibles dans un magasin, ou de les remettre en vente ; un responsable valide au back-office, sur la caisse ou sur le téléphone de salle avec son PIN. Seule la disponibilité change : jamais le prix ni la TVA.<br><i>VEN-54 partie 1, livré le 18/11/2026 et ALLUMÉ SUR LE STAGING le 20/11/2026 (accord d&#39;Ahmed du 18/11, après la revue de sécurité vague 1) : le type PRODUCT_AVAILABILITY est dans la liste des types allumés du staging local ; preuve de bout en bout sur le commerce fictif « Épicerie Lumière (démo) » (proposition créée par une clé d&#39;assistant, relue par le propriétaire, refusée ; produit inchangé). La production n&#39;existe pas encore. Famille Catalogue ; outil MCP propose_product_availability (store, 1 à 20 produits, available booléen). Seconde écriture dédiée « disponibilité seule » : prix et TVA de la ligne du magasin relus bruts et jamais remplacés (« hérité » reste hérité), prouvé sur cinq cas en base et par l&#39;API. Périmée si la fiche ou le magasin a changé entre-temps. Effet : produit retiré de la vente et du scan du magasin (caisses à leur prochaine synchronisation, menu en ligne tout de suite) ; une ligne déjà au panier reste vendable jusqu&#39;au relancement de l&#39;app. Rendu par l&#39;écran de décision générique, sans code d&#39;écran propre. Refusés : produits à variantes et variantes (jusqu&#39;à VEN-86), produit archivé, déjà dans l&#39;état demandé. Preuves sur la vraie stack : back-office, iPhone, iPad, Android téléphone et tablette, MCP (FR, arabe, sombre).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-133, RG-MCP-134, RG-MCP-122</td><td>VEN-54</td><td><a href="/VendoraSystem-docs/preuves/2026-11-18-disponibilite-produit">📷</a></td></tr></tbody></table><h2 id="types-de-proposition-livres-eteints-par-defaut-ven-54" tabindex="-1">Types de proposition livrés, éteints par défaut (VEN-54) <a class="header-anchor" href="#types-de-proposition-livres-eteints-par-defaut-ven-54" aria-label="Permalink to &quot;Types de proposition livrés, éteints par défaut (VEN-54)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Modifier la fiche d&#39;un produit, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de corriger la fiche d&#39;un produit : nom, catégorie, code-barres, coût d&#39;achat, suivi de stock, titres-restaurant. Un responsable valide au back-office ; la fiche change alors dans tous les magasins concernés. Jamais le prix de vente ni la TVA.<br><i>VEN-49 lot 2 (MCP-ECRITURE-PRODUIT-MODIFIER), livré le 18/11/2026 mais LIVRÉ ÉTEINT : le type PRODUCT_UPDATE n&#39;est pas dans la liste par défaut des types allumés, Vendora l&#39;allume type par type ; statut « partiel » tant qu&#39;il n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_product (action update). Six champs ouverts et eux seuls : nom (120 caractères au plus), catégorie ou « sans catégorie », code-barres, coût d&#39;achat, suivi de stock, éligibilité titres-restaurant. Fermés : prix de vente (c&#39;est le type changement de prix), TVA, référence, poids, péremption, menu en ligne, allergènes et toute version. Décidé au back-office seulement ; le contenu ne garde que les écarts avec leur valeur d&#39;avant. Une seule modification en attente par produit : une seconde la remplace. Périmée si la fiche a changé entre-temps (prix compris), si la catégorie ou le produit a disparu, ou si le code-barres visé a été pris. Code-barres : codes commençant par 20 à 29 refusés (étiquettes de balance, cartes de fidélité). Produits à variantes et produits archivés refusés. Serveur et MCP faits ; apps caisse et back-office : rendu générique et tests de rendu, aucun écran nouveau. Dossier de preuves en cours de production.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-135, RG-MCP-137, RG-MCP-122</td><td>VEN-49</td><td><a href="/VendoraSystem-docs/preuves/2026-11-18-produit-modifier">📷</a></td></tr><tr><td><strong>Retirer un produit de la vente ou l&#39;y remettre, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de retirer un produit de la vente dans tous les magasins, ou de l&#39;y remettre ; un responsable valide au back-office. Réversible : jamais une suppression, les ventes passées ne changent pas.<br><i>VEN-49 lot 2 (MCP-ECRITURE-PRODUIT-MODIFIER), livré le 18/11/2026 mais LIVRÉ ÉTEINT : le type PRODUCT_ARCHIVE n&#39;est pas dans la liste par défaut des types allumés ; statut « partiel » tant qu&#39;il n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_product (actions archive et restore). Aucune suppression : le produit reste dans le catalogue. Une ligne déjà au panier reste vendable jusqu&#39;au relancement de l&#39;app ; addition ouverte, commande en ligne déjà payée et retour d&#39;une vente passée restent possibles, au taux d&#39;origine. Remise en vente : la limite de produits de la formule est vérifiée à la validation ; si elle est atteinte, rien n&#39;est appliqué et la proposition reste en attente. Refusé si le produit est déjà dans l&#39;état demandé, ou si la proposition inverse attend encore. Périmée si la fiche a changé. L&#39;écran distingue le retrait d&#39;une rupture du jour (type disponibilité). Serveur et MCP faits ; apps caisse et back-office : rendu générique et tests de rendu, aucun écran nouveau. Dossier de preuves en cours de production.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-136, RG-MCP-137, RG-MCP-122</td><td>VEN-49</td><td><a href="/VendoraSystem-docs/preuves/2026-11-18-produit-modifier">📷</a></td></tr><tr><td><strong>Créer un produit, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose d&#39;ajouter un produit : nom, catégorie, prix TTC, code-barres, coût d&#39;achat, suivi de stock. Le taux de TVA est nommé par l&#39;assistant ou choisi par le responsable à la validation. Un responsable valide au back-office ; le produit n&#39;existe qu&#39;après.<br><i>VEN-49 lot 3 (MCP-ECRITURE-PRODUIT-CREER), livré le 19/11/2026 mais LIVRÉ ÉTEINT : le type PRODUCT_CREATE n&#39;est pas dans la liste par défaut des types allumés, Vendora l&#39;allume type par type ; statut « partiel » tant qu&#39;il n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_product (action create). Champs : nom, catégorie, prix TTC, code-barres, coût d&#39;achat, suivi de stock. TVA : l&#39;assistant nomme un taux (affiché « nom — pourcentage calculé ») ou laisse le responsable le choisir à la validation dans la liste des taux actifs, sans présélection ; jamais 0 % posé par l&#39;assistant ; jamais de taux par défaut. Avertissement quand le taux nommé diffère de celui de la catégorie. Décidé au back-office, en lecture seule sur les caisses. Refusés avant l&#39;appel : nom déjà pris, nom à caractère invisible ou à guillemets. Produit vendu et scellé au bon taux sur iOS et Android (euro et dinar testés). Revue de sécurité complète faite (docs/securite/MCP-ECRITURE-PRODUIT-CREER.md). Serveur et MCP faits ; apps caisse et back-office : rendu générique et tests de rendu, aucun écran nouveau. Reste avant la production : VEN-94 (addition scellée à 0 % si la caisse n&#39;a pas encore le produit), écran citant le taux choisi dans la case, taux filtrés par pays pour un magasin tunisien, avis d&#39;experts ; texte arabe à relire. Allumage sur le staging sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-140, RG-MCP-141, RG-MCP-137, RG-MCP-138, RG-MCP-139</td><td>VEN-49</td><td><a href="/VendoraSystem-docs/preuves/2026-11-19-produit-creer">📷</a></td></tr><tr><td><strong>Étendre un produit à tous les magasins, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose d&#39;étendre à tous les magasins un produit propre à un magasin ; seul le propriétaire ou un administrateur valide, au back-office. Le choix est définitif ; le produit arrive au prix et à la TVA de sa fiche.<br><i>VEN-49 lot 5 (MCP-ECRITURE-PRODUIT-ETENDRE), livré le 20/11/2026 mais LIVRÉ ÉTEINT : le type PRODUCT_PROMOTE n&#39;est pas dans la liste par défaut des types allumés ; statut « partiel » tant qu&#39;il n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_product (action promote). Seul le produit est proposé (aucun prix, TVA ni nom). Validation réservée au propriétaire ou à un administrateur (déroge à RG-MCP-91) : un gérant qui valide reçoit un refus et la proposition reste en attente. Case de confirmation, choix définitif. Le produit arrive sur les caisses de tous les magasins au prix et au taux de TVA de sa fiche ; les prix et taux propres au magasin d&#39;origine restent propres à ce magasin ; stock du magasin d&#39;origine, autres magasins à zéro ; ventes passées inchangées. Avertissement si un produit du même nom est propre à un autre magasin. Refusés : produit déjà commun, retiré de la vente, à variantes, magasin d&#39;une autre devise ou d&#39;un autre pays fiscal, nom déjà porté par un produit de l&#39;entreprise, accès limité à des magasins. Même refus de devise, de pays et de variantes pour le bouton « Rendre disponible dans tous les magasins » de la fiche produit (RG-MSTORE-19). Décidé au back-office, en lecture seule sur les caisses. Aide et captures : centre d&#39;aide mis à jour (FR, EN, AR). Reste : allumage sur accord d&#39;Ahmed, VEN-95 (devise des caisses), arabe à relire.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-145, RG-MSTORE-19, RG-MCP-137, RG-MCP-139</td><td>VEN-49</td><td><a href="/VendoraSystem-docs/preuves/2026-11-20-produit-etendre">📷</a></td></tr><tr><td><strong>Changer plusieurs prix en une fois, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de changer le prix de 1 à 100 produits d&#39;un magasin ou de toute l&#39;entreprise : nouveaux prix par produit, ou même hausse ou baisse en montant ou en pourcentage calculée par Vendora. Un responsable valide, avec une case de confirmation dès deux produits ; tout ou rien.<br><i>VEN-51 (MCP-ECRITURE-PRIX-GROUPE), livré le 20/11/2026 mais LIVRÉ ÉTEINT : la forme groupée du type PRICE_CHANGE est allumée par son propre jeton PRICE_CHANGE_GROUP, absent de la liste par défaut ; le prix simple (VEN-34) ne change pas d&#39;un octet. Statut « partiel » tant que le jeton n&#39;est pas allumé. Famille Catalogue ; outil MCP propose_price_changes. De 1 à 100 produits, une seule portée (un magasin, ou toute l&#39;entreprise), une seule devise. Trois façons : un prix par produit, ou une même hausse ou baisse en montant ou en pourcentage (−90 % à +100 %) calculée par le serveur en entiers, arrondie au centime (millime) loin de zéro, sans arrondi commercial. L&#39;écran montre prix avant et après, écart, taux de marque avant et après, lignes signalées « Sous le coût » et « Écart fort », écart cumulé signé. Un prix sous le coût est signalé, jamais refusé : note de revente à perte. Case de confirmation imposée par le serveur dès deux produits ; groupe d&#39;un magasin décidé au back-office ou sur la caisse sous PIN, groupe de l&#39;entreprise au back-office seul. Tout ou rien, périmée si un prix, un produit, un magasin ou une devise a changé ; la TVA, les ventes déjà enregistrées et les commandes saisies ne changent pas ; un prix propre à un magasin le reste. Corrige au passage setPriceOnly, qui ne relisait pas le produit sous verrou. Aide : centre d&#39;aide mis à jour (FR, EN, AR). Reste : allumage sur accord d&#39;Ahmed, avis d&#39;un juriste sur la revente à perte avant la production (France et Tunisie), captures iPad et tablette Android, arabe à relire (l&#39;écran dit « marge » là où le français dit « taux de marque »).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-146, RG-MCP-147, RG-MCP-116, RG-MCP-137, RG-MCP-139</td><td>VEN-51</td><td><a href="/VendoraSystem-docs/preuves/2026-11-20-prix-groupe">📷</a></td></tr><tr><td><strong>Créer ou modifier une catégorie, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de créer une catégorie, de la renommer, de la ranger dans une autre ou au premier niveau, ou de changer son ordre sur la borne, le menu en ligne et le back-office. Un responsable valide au back-office ; sur les caisses, lecture seule.<br><i>VEN-50 lot 1 (MCP-ECRITURE-CATEGORIES), livré le 20/11/2026 mais LIVRÉ ÉTEINT : les types CATEGORY_CREATE et CATEGORY_UPDATE ne sont pas dans la liste par défaut des types allumés ; statut « partiel » tant qu&#39;ils ne sont pas allumés. Famille Catalogue ; outil MCP propose_category (actions create et update). L&#39;assistant crée une catégorie, ou la renomme, la range dans une autre catégorie ou au premier niveau, change son ordre (un nombre, ou « en premier » / « en dernier » calculé par le serveur à la validation). Une seule catégorie par proposition ; ni couleur ni icône, ni suppression. L&#39;écran montre le chemin (« Carte › Desserts »), la position (« 1 sur 5 »), avant → après, « 3 changements » et des notes toutes accompagnées d&#39;une icône d&#39;information : rapports par catégorie renommés même pour les périodes passées, produits et sous-catégories qui suivent un déplacement, ventes déjà enregistrées inchangées, et surtout l&#39;ordre vaut pour la borne, le menu en ligne et le back-office, pas pour les boutons de la caisse. Décidé au back-office par un responsable, sans case de confirmation (risque faible, réversible) ; en lecture seule sur les caisses. Refusés : nom déjà pris par une autre catégorie (plus strict que le back-office), plus de trois niveaux, catégorie rangée dans sa propre branche, nom vide, trop long, à guillemets ou à caractère invisible, accès limité à des magasins. Périmée si la catégorie, son parent ou son nom ont changé. Corrige au passage deux défauts : un verrou d&#39;arbre contre les cycles de catégories par deux déplacements croisés (RG-CAT-94, import CSV compris) et une règle d&#39;ordre unique sur le back-office, le menu en ligne et la borne iOS et Android (RG-CAT-93). Aide : centre d&#39;aide mis à jour (FR, EN, AR). Reste : allumage sur accord d&#39;Ahmed, arabe à relire, défauts cosmétiques des écrans de proposition (libellé « Catégories au même niveau » ambigu pour un déplacement, ligne de chemin alignée à gauche en arabe au back-office, notes sans marge sur iOS).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-148, RG-MCP-149, RG-MCP-150, RG-MCP-137, RG-MCP-139</td><td>VEN-50</td><td><a href="/VendoraSystem-docs/preuves/2026-11-20-categories">📷</a></td></tr><tr><td><strong>Modifier l&#39;écran de vente, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose d&#39;ajouter, déplacer, redimensionner ou retirer des boutons de l&#39;écran de vente d&#39;un magasin. Un responsable valide au back-office ; les caisses du magasin reçoivent le nouvel écran ; retour en arrière en un clic.<br><i>VEN-50 lot 3 (MCP-ECRITURE-ECRAN-VENTE), 3-A et 3-B livrés le 22/11/2026, LIVRÉ ÉTEINT (type SALES_LAYOUT_UPDATE). Jusqu&#39;à 64 opérations rejouées dans l&#39;ordre ; refus OCCUPIED, OUT_OF_GRID, PAGE_FULL, OTHER_STORE ; périmée seulement si les pages ont changé ; écran publié égal au geste humain, version précédente restaurable. 3-B : l&#39;assistant lit l&#39;écran (get_sales_layout) puis propose toutes les opérations en une fois (propose_sales_layout) ; caisses iOS et Android en lecture seule (opérations avec icônes, décision au back-office), la caisse garde la page ouverte et le panier après validation. Allumage sur accord d&#39;Ahmed.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-155, RG-THEME-19, RG-MCP-156</td><td>VEN-50</td><td><a href="/VendoraSystem-docs/preuves/2026-11-22-ecran-vente-3a">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-22-ecran-vente-3b">📷</a></td></tr><tr><td><strong>Créer ou modifier un groupe de modificateurs, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de créer un groupe de modificateurs (sauces, cuissons, suppléments) ou de le modifier : prix d&#39;un supplément, option ajoutée, renommée ou retirée, nombre de choix, désactivation. Un responsable valide au back-office ; sur les caisses, lecture seule ; après validation, la caisse propose le nouveau supplément.<br><i>VEN-50 lots 2a-A et 2a-B (MCP-ECRITURE-MODIFICATEURS-2A et -2A-MCP), livrés le 21/11/2026 mais LIVRÉS ÉTEINTS : les types MODIFIER_GROUP_CREATE et MODIFIER_GROUP_UPDATE ne sont pas dans la liste par défaut des types allumés ; statut « partiel » tant qu&#39;ils ne sont pas allumés. Famille Catalogue ; outils MCP propose_modifier_group (create, update) et list_modifier_groups (lecture, dans l&#39;ordre du serveur). Un groupe vaut pour tous les magasins : accès complet exigé. Modification par opérations appliquées dans l&#39;ordre (ajouter, renommer, changer le prix, retirer ; 30 au plus), jamais le groupe recopié. Suppléments de 0 au plafond, dans l&#39;unique devise du commerce ; commerce multi-devise : supplément refusé, montants sans symbole, ou cachés si les décimales diffèrent (euro et dinar). Écarts signalés, jamais refusés : hausse ou baisse de plus de 30 %, passage à payant ou à gratuit, retrait (case de confirmation imposée), « Boisson alcoolisée ? ». L&#39;assistant ne propose jamais une boisson alcoolisée comme supplément : il propose un produit à part. Validation au back-office seul, identique au geste humain ; périmée si le groupe, sa version, un produit rattaché, le nom ou la devise ont changé. Ventes scellées, commandes en salle et paniers en attente gardent leurs suppléments ; une commande en ligne envoyée après validation suit le nouveau groupe (testé). Lot 2c (21/11, vague A) : l&#39;assistant propose aussi de rattacher ou de détacher un groupe (type MODIFIER_GROUP_ATTACH, éteint) — cibles sans effet refusées, taux de TVA par produit et par magasin, case jugée à la décision, une catégorie ne couvre pas ses sous-catégories. Aide mise à jour (FR, EN, AR). Banc d&#39;évaluation : passe complète 210/210. Reste : allumage sur accord d&#39;Ahmed ; avant production, décision sur les suppléments alcoolisés et avis d&#39;un expert-comptable (France, Tunisie) ; arabe et anglais à relire ; phrase « prochaine synchronisation » affichée deux fois sur une proposition appliquée (tous types, VEN-109).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-151, RG-MCP-152, RG-MCP-153, RG-CAT-95, RG-MCP-139, RG-MCP-154</td><td>VEN-50</td><td><a href="/VendoraSystem-docs/preuves/2026-11-20-modificateurs-2a">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-21-modificateurs-2c">📷</a></td></tr><tr><td><strong>Importer des produits, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de créer ou de mettre à jour jusqu&#39;à 100 produits d&#39;un coup. Un responsable vérifie au back-office le tableau des produits, la répartition des taux de TVA des nouveaux produits et les écarts de prix, coche une case qui nomme chaque taux, puis tout est appliqué ou rien.<br><i>VEN-50 lot 5 (MCP-ECRITURE-IMPORT, livrables A le 22/11 et B le 27/11/2026), LIVRÉ ÉTEINT (type CATALOG_IMPORT, outil propose_catalog_import). L&#39;assistant propose de créer ou mettre à jour jusqu&#39;à 100 produits ; un responsable vérifie au back-office le tableau, la répartition des taux de TVA des nouveaux produits et les écarts de prix, coche une case qui nomme chaque taux, puis tout est appliqué ou rien. TVA d&#39;un produit existant jamais changée ; nouveau produit sans taux refusé, taux jamais deviné par l&#39;assistant ; prix fournisseur jamais pris pour un prix de vente ; magasin tunisien limité à 7, 13 et 19 %. Caisses iOS et Android en lecture seule. Reste : allumage sur accord d&#39;Ahmed, captures, avis humains (expert-comptable FR et TN, LNE).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-157, RG-MCP-158, RG-CAT-96, RG-CAT-97</td><td>VEN-50</td><td><a href="/VendoraSystem-docs/preuves/2026-11-22-import-a">📷</a></td></tr><tr><td><strong>Corriger le stock et déclarer une perte, proposés par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de corriger le stock après un comptage ou de déclarer une casse, une péremption ou une perte. Un responsable valide au back-office avec son PIN ; le stock change seulement par des mouvements signés, marqués « préparé par l&#39;assistant » au journal.<br><i>VEN-52 livrables A, B, CAISSES et C1 livrés le 27/11/2026, LIVRÉS ÉTEINTS (STOCK_ADJUSTMENT, STOCK_LOSS, INITIAL_STOCK, LOW_STOCK_THRESHOLD, outils de l&#39;assistant associés). Correction après comptage et perte : écart recalculé à la validation, motif choisi par le validateur (jamais « vol » pré-rempli), PIN au back-office ou sur la caisse, téléphone de salle en lecture seule. Stock initial en tout ou rien (produit sans mouvement), seuil de stock bas valable pour tous les magasins. Journal « préparé par l&#39;assistant · validé par {nom} ». Reste : C2 (inventaire, lot périmé), stock initial et seuil décidés sur la caisse (E, 28/11) ; allumage sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-159, RG-STOCK-26</td><td>VEN-52</td><td></td></tr><tr><td><strong>Réceptionner un bon de commande, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant prépare la réception d&#39;un bon déjà envoyé (ce qui est arrivé, ce qui manque) ; un responsable vérifie au back-office les quantités et les coûts HT du bon, coche « marchandise effectivement reçue », et la réception entre au stock comme une réception faite à la main.<br><i>VEN-53 livrable A (MCP-ECRITURE-ACHATS) livré le 27/11/2026, LIVRÉ ÉTEINT (type PURCHASE_RECEIPT). Lignes non citées reçues ou non (choix obligatoire) ; coûts du bon seulement, affichés HT ; case toujours exigée ; date = validation, avertissement si le mois change ; lot ou DLC exigés → réception à la main ; numéro de bon partagé entre magasins → l&#39;assistant demande le magasin ; mention « préparé par l&#39;assistant » sur la réception et au journal de stock. Fournisseurs et prix d&#39;achat (B), transferts (C), outils de l&#39;assistant (D) et décision sur la caisse (E) livrés ; allumage sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-164, RG-SUP-21</td><td>VEN-53</td><td></td></tr><tr><td><strong>Créer ou modifier un fournisseur, changer un prix d&#39;achat, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant propose de créer un fournisseur, de modifier ses coordonnées ou de changer des prix d&#39;achat ; un responsable valide au back-office. Seul le prix change : ni le coût moyen, ni l&#39;historique, ni les bons existants.<br><i>VEN-53 livrable B (MCP-ECRITURE-ACHATS-B) livré le 27/11/2026, LIVRÉ ÉTEINT (SUPPLIER_CREATE, SUPPLIER_UPDATE, SUPPLIER_PRICE). Module « Fournisseurs et achats » exigé ; e-mail, adresse, devise et notes jamais ouverts à l&#39;assistant ; nom unique ; case pour une désactivation ou un écart de prix de plus de 30 %. Outils de l&#39;assistant (D) et caisse (E) livrés ; allumage sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-165, RG-SUP-22</td><td>VEN-53</td><td></td></tr><tr><td><strong>Préparer un transfert entre magasins, proposé par l&#39;assistant</strong><br><span class="muted">L&#39;assistant prépare un transfert de produits d&#39;un magasin vers un autre ; un responsable du magasin d&#39;origine le valide au back-office. Le transfert est créé validé mais jamais expédié : l&#39;expédition et la réception restent à faire à la main.<br><i>VEN-53 livrable C (MCP-ECRITURE-ACHATS-C) livré le 27/11/2026, LIVRÉ ÉTEINT (STOCK_TRANSFER). Aucun mouvement de stock à la validation ; destination hors de l&#39;accès « introuvable » ; quantité au-dessus du stock signalée ; mention « préparé par l&#39;assistant » sur la page Transferts. Outils de l&#39;assistant (D) et caisse (E) livrés ; allumage sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MCP-166, RG-MSTORE-20</td><td>VEN-53</td><td></td></tr><tr><td><strong>Outils de l&#39;assistant pour les achats et le transfert</strong><br><span class="muted">L&#39;assistant sait proposer, dans la conversation, la réception d&#39;un bon de commande (quantités en unités ou en cartons), la création ou la modification d&#39;un fournisseur, un nouveau prix d&#39;achat et un transfert entre magasins. Il ne fixe jamais un coût, une date ni l&#39;e-mail d&#39;un fournisseur ; un responsable valide chaque proposition.<br><i>VEN-53 livrable D (MCP-ECRITURE-ACHATS-D) livré le 27/11/2026, LIVRÉ ÉTEINT : outils propose_purchase_receipt, propose_supplier, propose_supplier_prices, propose_stock_transfer, listés seulement si leur type est allumé. Évaluations w90 → w97 et i18 prêtes ; passes réelles à l&#39;allumage, sur accord d&#39;Ahmed.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-167</td><td>VEN-53</td><td></td></tr></tbody></table><h2 id="lectures-de-l-assistant-—-catalogue" tabindex="-1">Lectures de l&#39;assistant — catalogue <a class="header-anchor" href="#lectures-de-l-assistant-—-catalogue" aria-label="Permalink to &quot;Lectures de l&#39;assistant — catalogue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Lectures du catalogue par l&#39;assistant : fiche produit complète, catégories et taux, date du jour</strong><br><span class="muted">L&#39;assistant voit pour un produit sa catégorie, sa portée (toute l&#39;entreprise ou un magasin), ses ruptures et ses prix par magasin (détaillés jusqu&#39;à six magasins). Il peut lister les catégories et les taux de TVA actifs et connaît la date du jour de chaque magasin. Pour chaque catégorie, il connaît aussi son ordre et sa position parmi ses voisines.<br><i>VEN-49 lot 4b (MCP-ECRITURE-PRODUIT-LIRE), livré le 19/11/2026, lecture seule. Outil find_product complété (catégorie, portée, ruptures et prix par magasin, plafonné à six magasins avec avertissement au-delà), nouvel outil catalog_reference (catégories et taux de TVA actifs), date et heure du jour de chaque magasin dans list_stores. Preuve : rapports d&#39;évaluation mcp/evals/reports/2026-11-19-ven49-lire-* (questions w31 à w36 et i09), pas de captures car aucun écran ne change. Complété par VEN-51 (20/11/2026) : paramètre in_category, qui donne la liste des produits d&#39;une catégorie (« tous les cafés ») pour les propositions de prix groupé ; quand un mot désigne plusieurs catégories, l&#39;assistant demande laquelle. Complété par VEN-50 (20/11/2026, RG-MCP-150) : chaque catégorie rend aussi son ordre (sortOrder) et sa position parmi les catégories du même niveau (« 2 sur 5 »), selon la règle d&#39;ordre unique du serveur et calculée sur la liste complète avant la troncature à 100 catégories ; l&#39;assistant s&#39;en sert pour proposer « en premier » ou un ordre précis.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-142, RG-MCP-150</td><td>MCP-ECRITURE-PRODUIT-LIRE, VEN-50</td><td><a href="/VendoraSystem-docs/preuves/2026-11-20-categories">📷</a></td></tr><tr><td><strong>Un accès limité à des magasins ne lit que leurs produits</strong><br><span class="muted">Un accès de l&#39;assistant ou une clé limités à certains magasins ne voit plus les produits propres aux autres magasins : ni le nom, ni le prix, ni le coût d&#39;achat, ni le code-barres.<br><i>Correctif de sécurité VEN-49 lot 4a, 19/11/2026 (rapport docs/securite/MCP-LECTURE-ACCES-LIMITE.md ; migrations V125 à V127). Depuis le 11/11/2026, la restriction par magasin ne couvrait pas la table des produits : fuite fermée sur toutes les routes de lecture et l&#39;outil find_product, avec garde automatique sur le schéma. Staging de démonstration seulement, aucune production. À déployer sur le staging dès que les builds Render repartent.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-143</td><td>MCP-LECTURE-ACCES-LIMITE</td><td></td></tr></tbody></table><h2 id="a-faire-—-jalons-suivants-du-projet-«-ecriture-»" tabindex="-1">À faire — jalons suivants du projet « écriture » <a class="header-anchor" href="#a-faire-—-jalons-suivants-du-projet-«-ecriture-»" aria-label="Permalink to &quot;À faire — jalons suivants du projet « écriture »&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Catalogue : fiches produit, catégories, modificateurs, écran de vente, import, prix groupés</strong><br><span class="muted">L&#39;assistant pourra proposer de créer, modifier, archiver ou mettre en promotion des produits, de gérer catégories, modificateurs et écran de vente, d&#39;importer un lot de produits et de changer plusieurs prix d&#39;un coup.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-49, VEN-50, VEN-51</td><td></td></tr><tr><td><strong>Stock : ajustements, pertes, lots, inventaires, seuils</strong><br><span class="muted">Proposer des mouvements de stock (toujours signés, jamais une valeur écrasée), le démarrage d&#39;un inventaire, des seuils d&#39;alerte et un stock initial.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-52</td><td></td></tr><tr><td><strong>Achats : réceptions, fournisseurs, prix fournisseur, transferts</strong><br><span class="muted">Compléter le bon de commande avec la réception, la création et la mise à jour de fournisseurs, leurs prix et les transferts entre magasins.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-53</td><td></td></tr><tr><td><strong>Restaurant : formules, fiches techniques, plan de salle, postes de préparation</strong><br><span class="muted">Proposer de publier une formule ou une fiche technique, de modifier le plan de salle et les postes de préparation (la disponibilité d&#39;un produit est livrée à part, éteinte).<br><i>VEN-54 partie 2, à cadrer à part : formules, recettes (fiches techniques), plan de salle, postes de préparation. La partie 1, la disponibilité d&#39;un produit, est livrée (fiche « Disponibilité d&#39;un produit proposée par l&#39;assistant »). Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-54</td><td></td></tr><tr><td><strong>Clients : programme de fidélité</strong><br><span class="muted">Proposer le réglage du programme de fidélité ; les données nominatives des clients restent en second temps, après avis juridique.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-55</td><td></td></tr><tr><td><strong>Réglages : magasin, ticket, apparence, rapports, canaux</strong><br><span class="muted">Proposer des réglages du commerce (hors fiscal, TVA, argent et sécurité, toujours exclus) : informations du magasin, profil de ticket, apparence, bornes, rapports, canaux, profils de salle.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-56</td><td></td></tr><tr><td><strong>Appareils : appairage, nom, réglages et configuration</strong><br><span class="muted">Proposer l&#39;ajout et le réglage d&#39;un appareil, sans que le code d&#39;appairage figure jamais dans une proposition.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-60</td><td></td></tr><tr><td><strong>Activité de l&#39;assistant et annulation d&#39;une proposition appliquée</strong><br><span class="muted">Voir ce que l&#39;assistant a fait et annuler ce qui peut l&#39;être.<br><i>Prévu par la matrice « back-office → propositions » (docs/lots/MCP-ECRITURE-MATRICE.md) ; livré éteint, allumé seulement après la revue de sécurité de la famille ; aucune échéance annoncée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-MCP-105</td><td>VEN-57</td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Types de proposition des jalons 2 à 7 (catalogue, stock, achats, restaurant, clients, réglages, appareils : 42 types prévus, listés dans docs/lots/MCP-ECRITURE-MATRICE.md), chacun livré éteint puis allumé après sa revue de sécurité.</li><li>Activité de l&#39;assistant et annulation d&#39;une proposition appliquée (VEN-57).</li><li>Écarts d&#39;écran laissés et points à faire acter par Ahmed : fiche de lot MCP-ECRITURE-SOCLE, section « Écarts constatés ».</li><li>Disponibilité d&#39;un produit (VEN-54 partie 1) livrée éteinte : allumage sur le staging puis revue de sécurité de la famille Catalogue, décision d&#39;Ahmed ; partie 2 (formules, recettes, plan de salle, postes de préparation) à cadrer.</li><li>Écarts laissés par la disponibilité d&#39;un produit (README des captures 2026-11-18-disponibilite-produit) : phrase de péremption qui ne dit pas « prix » ou « TVA » et change de cause à la relecture, texte du refus inverse de l&#39;outil MCP encore suivi de « (content.product) », résumé PIN en arabe dont les deux-points colle au nom latin, code-barres sous le nom visible sur Android seulement, bouton long sur deux lignes sur iPad en arabe.</li><li>Arabe de la disponibilité d&#39;un produit à faire relire par un natif ; produits à variantes refusés jusqu&#39;à VEN-86.</li><li>Écarts du socle soldés le 18/11 : parenthèse de l&#39;écart coupée en arabe sur la feuille PIN Android (corrigée), texte de l&#39;assistant absent de « Back-office seulement » sur les caisses (décision d&#39;Ahmed du 17/11), effectifs du filtre de famille des caisses comptés sur toute la liste (voulu : les caisses n&#39;ont pas de filtre de statut).</li><li>Allumage de la disponibilité d&#39;un produit sur le staging : décidé le 18/11/2026, pas encore effectif (déploiements Render bloqués) ; la fiche reste « partiel » jusqu&#39;à l&#39;allumage.</li><li>Allumage sur le staging des types « modifier la fiche d&#39;un produit » et « retirer un produit de la vente » (VEN-49) : après la tranche de revue et l&#39;accord d&#39;Ahmed ; avis d&#39;un spécialiste des titres-restaurant avant la production ; arabe de ces deux types à faire relire par un natif.</li><li>Correctif du 19/11 (VEN-49 lot 4a, rapport docs/securite/MCP-LECTURE-ACCES-LIMITE.md) : un accès limité à des magasins ne lit plus les produits propres aux autres magasins ; à déployer sur le staging dès que les builds Render repartent</li><li>Allumage de « Étendre un produit à tous les magasins » (VEN-49 lot 5) sur accord d&#39;Ahmed ; VEN-95 (devise des caisses : un magasin d&#39;une autre devise désarchivé après l&#39;extension reçoit le produit) ; arabe à relire par un natif.</li><li>Allumage de « Créer ou modifier un groupe de modificateurs » (VEN-50 lots 2a-A et 2a-B, types MODIFIER_GROUP_CREATE et MODIFIER_GROUP_UPDATE) sur accord d&#39;Ahmed ; avant production : suppléments alcoolisés et avis d&#39;un expert-comptable ; arabe et anglais à relire ; rattachement aux produits au lot 2c.</li><li>Allumage de « Créer ou modifier une catégorie » (VEN-50 lot 1, types CATEGORY_CREATE et CATEGORY_UPDATE) sur accord d&#39;Ahmed ; arabe à relire ; défauts cosmétiques des écrans de proposition (libellé « Catégories au même niveau » d&#39;un déplacement, chemin aligné à gauche en arabe au back-office, notes sans marge sur iOS).</li><li>Allumage de « Changer plusieurs prix en une fois » (VEN-51, jeton PRICE_CHANGE_GROUP) sur accord d&#39;Ahmed ; avis d&#39;un juriste ou d&#39;un expert-comptable sur la revente à perte (note affichée, prix sous le coût signalé mais non bloqué) avant la production, en France et en Tunisie ; captures iPad et tablette Android ; arabe à relire par un natif.</li></ul>',18)])])}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
